"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73447"],{70594(e){e.exports=JSON.parse('{"id":"F388","slug":"annualized-loss-expectancy","name":"Annualized Loss Expectancy (Cyber Risk)","subject":"Risk Management","section":"Risk","topic":"Operational risk and cyber risk","level":"Beginner","aliases":["ALE","SLE","ARO","cyber risk quantification","security investment return"],"formula":{"latex":"ALE=SLE\\\\times ARO,\\\\quad SLE=AV\\\\times EF","also":[],"text":"Annualized loss expectancy = Single loss expectancy x Annual rate of occurrence; Single loss expectancy = Asset value x Exposure factor"},"symbols":[{"symbol":"AV","meaning":"Value of the asset at risk","unit":"money"},{"symbol":"EF","meaning":"Share of the asset lost in one incident","unit":"percent"},{"symbol":"SLE","meaning":"Single loss expectancy, the cost of one incident","unit":"money"},{"symbol":"ARO","meaning":"Annual rate of occurrence, expected incidents per year","unit":"number"}],"when_to_use":"Use it to put a money value on a cyber risk and decide whether a control is worth buying. A control is worth it if the drop in expected yearly loss exceeds its yearly cost.","worked_example":{"problem":"A customer database is worth 5,000,000. A breach would expose 30% of its value, and a breach is expected once every 5 years. A control costing 120,000 a year cuts the rate to once every 20 years.","inputs":{"av":5000000,"ef":30,"aro":0.2,"aro2":0.05,"cost":120000},"steps":[{"label":"SLE = asset value x exposure factor","working":"5,000,000 x 0.3","value":"1,500,000.00"},{"label":"ALE now = SLE x ARO","working":"1,500,000 x 0.2","value":"300,000.00"},{"label":"ALE with the control","working":"1,500,000 x 0.05","value":"75,000.00"},{"label":"Reduction in expected loss","working":"300000-75000","value":"225,000.00"},{"label":"Net benefit = saving - cost","working":"225000-120000","value":"105,000.00"}],"answer":"One incident costs 1,500,000.00, so the expected yearly loss is 300,000.00. With the control it falls to 75,000.00, a saving of 225,000.00 against a cost of 120,000, so the control gives a net benefit of 105,000.00."},"calculator":{"available":true,"inputs":[{"id":"av","label":"Asset value","unit":"money","type":"number","default":5000000,"hint":""},{"id":"ef","label":"Exposure factor","unit":"%","type":"number","default":30,"hint":""},{"id":"aro","label":"Incidents per year now","unit":"number","type":"number","default":0.2,"hint":""},{"id":"aro2","label":"Incidents per year with the control","unit":"number","type":"number","default":0.05,"hint":""},{"id":"cost","label":"Annual cost of the control","unit":"money","type":"number","default":120000,"hint":""}],"checks":[],"steps":[{"id":"sle","label":"SLE = asset value x exposure factor","expr":"av*ef","format":"money"},{"id":"ale","label":"ALE now = SLE x ARO","expr":"sle*aro","format":"money"},{"id":"ale2","label":"ALE with the control","expr":"sle*aro2","format":"money"},{"id":"saving","label":"Reduction in expected loss","expr":"ale-ale2","format":"money"},{"id":"net","label":"Net benefit = saving - cost","expr":"saving-cost","format":"money"}],"results":["ale","net"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"sle":1500000,"ale":300000,"ale2":75000,"saving":225000,"net":105000}},"finder":{"finds":"The yearly expected cost of a cyber risk and whether a control pays","needs":"Asset value, exposure, incident rates, control cost"},"related":[{"slug":"op-risk-capital-bia","name":"Operational Risk: Basic Indicator Capital and Expected Loss"},{"slug":"expected-value","name":"Expected Value"}],"related_ids":["F389","F058"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><mi>L</mi><mi>E</mi><mo>=</mo><mi>S</mi><mi>L</mi><mi>E</mi><mo>\xd7</mo><mi>A</mi><mi>R</mi><mi>O</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>S</mi><mi>L</mi><mi>E</mi><mo>=</mo><mi>A</mi><mi>V</mi><mo>\xd7</mo><mi>E</mi><mi>F</mi></mrow><annotation encoding=\\"application/x-tex\\">ALE=SLE\\\\times ARO,\\\\quad SLE=AV\\\\times EF</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>A</mi><mi>L</mi><mi>E</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle ALE</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>S</mi><mi>L</mi><mi>E</mi><mo>\xd7</mo><mi>A</mi><mi>R</mi><mi>O</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =SLE\\\\times ARO</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>S</mi><mi>L</mi><mi>E</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle SLE</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>A</mi><mi>V</mi><mo>\xd7</mo><mi>E</mi><mi>F</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =AV\\\\times EF</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"annual-report-scorecard","name":"Annual Report Scorecard"},"next":{"slug":"annualized-hpr","name":"Annualizing a Holding Period Return"},"lesson":null,"total":522}')}}]);